// Item is a single stored record.
type Item struct {
	ID        int       `json:"id"`
	Name      string    `json:"name"`
	CreatedAt time.Time `json:"created_at"`
}

// Store is a mutex-protected, in-memory item store.
type Store struct {
	mu     sync.Mutex
	nextID int
	items  []Item
}

func NewStore() *Store {
	return &Store{nextID: 1}
}

func (s *Store) Create(name string) Item {
	s.mu.Lock()
	defer s.mu.Unlock()
	item := Item{
		ID:        s.nextID,
		Name:      name,
		CreatedAt: time.Now().UTC(),
	}
	s.nextID++
	s.items = append(s.items, item)
	return item
}

func (s *Store) List() []Item {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := make([]Item, len(s.items))
	copy(out, s.items)
	return out
}

// Server holds shared dependencies for handlers.
type Server struct {
	store *Store
}

